@rendermode InteractiveServer
@using sv_3cc939ddd66b4e7e92da187cedc0b8d5.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book a Medical Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="book-appointment">
    <DataAnnotationsValidator />
    <CustomValidator @ref="customValidator" />

    @* ===== STEP 1 ===== *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label">Patient Name</label>
            <InputText class="form-control" @bind-Value="Model!.PatientName" />
            <ValidationMessage For="() => Model!.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label">Email</label>
            <InputText class="form-control" @bind-Value="Model!.Email" />
            <ValidationMessage For="() => Model!.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label">Phone</label>
            <InputText class="form-control" @bind-Value="Model!.Phone" />
            <ValidationMessage For="() => Model!.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label">Insurance Provider</label>
            <InputSelect class="form-select" @bind-Value="Model!.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model!.InsuranceProvider" />
        </div>
    </fieldset>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
            Next
        </button>
    }

    @* ===== STEP 2 ===== *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label">Preferred Doctor</label>
                <InputSelect class="form-select" @bind-Value="Model!.Doctor">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model!.Doctor" />
            </div>

            <div class="mb-3">
                <label class="form-label">Date</label>
                <InputDate class="form-control" @bind-Value="Model!.AppointmentDate"
                           @bind-Value:after="OnDateChanged" />
                <ValidationMessage For="() => Model!.AppointmentDate" />
                @if (Model!.AppointmentDate.HasValue && Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
                {
                    <div class="text-danger">Date must be in the future.</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label">Time Slot</label>
                <InputSelect class="form-select" @bind-Value="Model!.TimeSlot" disabled="@(!availableSlots.Any())">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model!.TimeSlot" />
                @if (!availableSlots.Any() && Model!.Doctor is not null && Model.AppointmentDate.HasValue)
                {
                    <div class="text-muted">Select a doctor and future date to see available slots.</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label">Reason for Visit</label>
                <InputTextArea class="form-control" @bind-Value="Model!.Reason" rows="3" />
                <ValidationMessage For="() => Model!.Reason" />
            </div>

            <div class="d-flex gap-2">
                <button type="button" class="btn btn-secondary" @onclick="BackToStep1">
                    Back
                </button>
                <button type="button" class="btn btn-outline-primary" @onclick="CheckAvailability"
                        disabled="@isChecking">
                    @(isChecking ? "Checking..." : "Check Availability")
                </button>
                <button type="submit" class="btn btn-success" disabled="@(!availabilityConfirmed || isSubmitting)">
                    @(isSubmitting ? "Booking..." : "Book Appointment")
                </button>
            </div>
        </fieldset>
    }
</EditForm>

@if (bookingConfirmed)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully for <strong>@Model!.PatientName</strong>
        with <strong>@Model.Doctor</strong> on @Model.AppointmentDate?.ToString("MMM dd, yyyy")
        at @Model.TimeSlot.
    </div>
}

@code {
    private BookAppointmentModel? Model { get; set; }
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isChecking;
    private bool isSubmitting;
    private bool availabilityConfirmed;
    private bool bookingConfirmed;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    protected override async Task OnInitializedAsync()
    {
        Model ??= new();
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate only step 1 fields manually
        var isValid = !string.IsNullOrWhiteSpace(Model!.PatientName)
                      && !string.IsNullOrWhiteSpace(Model.Email)
                      && new System.ComponentModel.DataAnnotations.EmailAddressAttribute().IsValid(Model.Email)
                      && !string.IsNullOrWhiteSpace(Model.Phone)
                      && !string.IsNullOrWhiteSpace(Model.InsuranceProvider);

        if (isValid)
        {
            showStep2 = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityConfirmed = false;
    }

    private async Task OnDateChanged()
    {
        availableSlots.Clear();
        availabilityConfirmed = false;

        if (!string.IsNullOrEmpty(Model!.Doctor) && Model.AppointmentDate.HasValue
            && Model.AppointmentDate.Value > DateOnly.FromDateTime(DateTime.Today))
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }

        Model.TimeSlot = null;
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        availabilityConfirmed = false;

        // Client-side guards before calling the server
        if (string.IsNullOrEmpty(Model!.Doctor)
            || !Model.AppointmentDate.HasValue
            || Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today)
            || string.IsNullOrEmpty(Model.TimeSlot)
            || string.IsNullOrWhiteSpace(Model.Reason))
        {
            customValidator?.DisplayErrors(new Dictionary<string, List<string>>
            {
                [string.IsNullOrEmpty(Model.Doctor) ? nameof(Model.Doctor) :
                 !Model.AppointmentDate.HasValue || Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today) ? nameof(Model.AppointmentDate) :
                 string.IsNullOrEmpty(Model.TimeSlot) ? nameof(Model.TimeSlot) :
                 nameof(Model.Reason)] = ["This field is required."]
            });
            return;
        }

        isChecking = true;

        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                Model.Email!, Model.InsuranceProvider!, Model.Doctor!, Model.TimeSlot!);

            if (errors.Count > 0)
            {
                customValidator?.DisplayErrors(errors);
            }
            else
            {
                availabilityConfirmed = true;
            }
        }
        finally
        {
            isChecking = false;
        }
    }

    private async Task HandleSubmit()
    {
        if (!availabilityConfirmed)
            return;

        if (Model!.AppointmentDate.HasValue
            && Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            return;
        }

        isSubmitting = true;

        try
        {
            // Simulate booking
            await Task.Delay(500);
            bookingConfirmed = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }
}
"}

